"""8-bit left rotation: rotl8(x, k) rotates x left by k bits within 8 bits."""

BITS: int = 8
MASK: int = 0xFF


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits.

    Requires 0 <= x <= 255 and 0 <= k <= 7. Bits shifted out of the
    high end wrap around into the low end. The result is in 0..255.
    """
    return ((x << k) | (x >> (BITS - k))) & MASK


def test_rotl8_zero_shift_is_identity() -> None:
    assert rotl8(0xA5, 0) == 0xA5


def test_rotl8_single_bit_wraps_from_high_to_low() -> None:
    assert rotl8(0b1000_0001, 1) == 0b0000_0011


def test_rotl8_high_bit_moves_to_bit_zero() -> None:
    assert rotl8(0x80, 1) == 0x01


def test_rotl8_nibble_swap() -> None:
    assert rotl8(0x12, 4) == 0x21


def test_rotl8_all_ones_is_fixed_point() -> None:
    for k in range(8):
        assert rotl8(0xFF, k) == 0xFF


def test_rotl8_result_stays_in_byte_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= MASK
